using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Runtime.InteropServices;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;
public static class WeldSevenTerrain{
 [StructLayout(LayoutKind.Sequential)]struct Vertex:IEquatable<Vertex>{public ulong a,b,c,d,e,f,g,h;public bool Equals(Vertex o)=>a==o.a&&b==o.b&&c==o.c&&d==o.d&&e==o.e&&f==o.f&&g==o.g&&h==o.h;public override bool Equals(object o)=>o is Vertex v&&Equals(v);public override int GetHashCode()=>HashCode.Combine(a,b,c,d,e,f,g,h);}
 public static string Main(){const string path="Assets/Track/BackyardReverse/DansBackyardReverse-Rounded reduced takeoff release-6.asset";EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);EditorUtility.UnloadUnusedAssetsImmediate();var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh.vertexBufferCount!=1||mesh.GetVertexBufferStride(0)!=64||mesh.subMeshCount!=1)throw new Exception("Unexpected mesh layout");Vertex[] vertices;using(var data=Mesh.AcquireReadOnlyMeshData(mesh))vertices=data[0].GetVertexData<Vertex>().ToArray();var unique=new List<Vertex>();var map=new Dictionary<Vertex,int>();var remap=new int[vertices.Length];for(int i=0;i<vertices.Length;i++){if(!map.TryGetValue(vertices[i],out int j)){j=unique.Count;map.Add(vertices[i],j);unique.Add(vertices[i]);}remap[i]=j;}File.WriteAllText("Docs/SevenCorrections/terrain-weld-count.txt",$"Exact unique vertices {unique.Count}/{vertices.Length}");if(unique.Count>vertices.Length*.70f)return "Insufficient exact duplication: "+unique.Count+"/"+vertices.Length;
 var indices=mesh.triangles;for(int i=0;i<indices.Length;i++){int old=indices[i];indices[i]=remap[old];if(!vertices[old].Equals(unique[indices[i]]))throw new Exception("Vertex data mismatch");}var copy=UnityEngine.Object.Instantiate(mesh);copy.SetVertexBufferParams(unique.Count,mesh.GetVertexAttributes());copy.SetVertexBufferData(unique.ToArray(),0,0,unique.Count,0,MeshUpdateFlags.DontRecalculateBounds);copy.SetIndexBufferParams(indices.Length,IndexFormat.UInt32);copy.SetIndexBufferData(indices,0,0,indices.Length,MeshUpdateFlags.DontRecalculateBounds);copy.subMeshCount=1;copy.SetSubMesh(0,new SubMeshDescriptor(0,indices.Length,MeshTopology.Triangles){bounds=mesh.bounds,vertexCount=unique.Count},MeshUpdateFlags.DontRecalculateBounds);copy.bounds=mesh.bounds;const string compact="Assets/Track/SevenCorrections/Exact compact pool release.asset";AssetDatabase.CreateAsset(copy,compact);if(new FileInfo(compact).Length>=100L*1024*1024)throw new Exception("Compacted asset still exceeds limit");EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");int refs=0;foreach(var mf in UnityEngine.Object.FindObjectsByType<MeshFilter>())if(AssetDatabase.GetAssetPath(mf.sharedMesh)==path){mf.sharedMesh=copy;refs++;}foreach(var mc in UnityEngine.Object.FindObjectsByType<MeshCollider>())if(AssetDatabase.GetAssetPath(mc.sharedMesh)==path){mc.sharedMesh=copy;refs++;}if(refs!=2)throw new Exception("Reference count "+refs);EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();long oldBytes=new FileInfo(path).Length;AssetDatabase.DeleteAsset(path);AssetDatabase.DeleteAsset("Assets/Track/SevenCorrections/Rounded pool release binary.asset");string result=$"PASS lossless vertex deduplication: vertices {vertices.Length} -> {unique.Count}; triangle indices={indices.Length}; every expanded vertex's 64 bytes identical, triangle order unchanged; bytes {oldBytes} -> {new FileInfo(compact).Length}; both renderer/collider reference compact mesh; global settings unchanged";File.WriteAllText("Docs/SevenCorrections/terrain-storage.txt",result);return result;}}
